<?php
 namespace Pterodactyl\Http\Middleware\Dezerx; use Closure; use Illuminate\Http\Request; use Illuminate\Http\JsonResponse; use Pterodactyl\Services\Dezerx\Demo; use Symfony\Component\HttpFoundation\Response; class DemoRestriction { private const READS = ['GET', 'HEAD', 'OPTIONS']; private const WRITES = ['auth/logout']; public function handle(Request $request, Closure $next): mixed { if (!Demo::is($request->user())) { return $next($request); } if ($request->is('admin', 'admin/*')) { return $this->refuse($request, 'The demo account cannot open the administrative area.'); } if (in_array($request->method(), self::READS, true)) { return $next($request); } foreach (self::WRITES as $path) { if ($request->is($path)) { return $next($request); } } return $this->refuse($request, Demo::REFUSAL); } private function refuse(Request $request, string $message): Response { if ($request->expectsJson() || $request->is('api/*')) { return new JsonResponse([ 'errors' => [[ 'code' => 'DemoAccount', 'status' => '403', 'detail' => $message, ]], ], 403); } abort(403, $message); } } 